-- Trail-network line geometry per park (GeoJSON FeatureCollection of
-- LineStrings), rendered as the map overlay on the park detail Location tab.
-- One row per park. See docs/poc/trail-overlay.md.

-- CreateTable
CREATE TABLE "ParkTrailGeometry" (
    "id" TEXT NOT NULL,
    "parkId" TEXT NOT NULL,
    "geojson" JSONB NOT NULL,
    "featureCount" INTEGER,
    "sourceName" TEXT,
    "sourceUrl" TEXT,
    "license" TEXT,
    "publishedDate" TIMESTAMP(3),
    "importedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "ParkTrailGeometry_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE UNIQUE INDEX "ParkTrailGeometry_parkId_key" ON "ParkTrailGeometry"("parkId");

-- AddForeignKey
ALTER TABLE "ParkTrailGeometry" ADD CONSTRAINT "ParkTrailGeometry_parkId_fkey" FOREIGN KEY ("parkId") REFERENCES "Park"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- Seed Brock Creek Multi-Use Trail System geometry (dollar-quoted -> no escaping; name-matched; safe no-op if the park is absent).
